    else:
        min_unmet = float(pulp.value(pulp.lpSum(unmet1[i, t] for i in range(n_items) for t in range(n_periods))) or 0.0)

    prob2, x2, inv2, unmet2 = build_model(minimize_inventory=True, target_unmet=min_unmet)
